import math
    import random
    import time

    LANGUAGE_WRAPPER = 'In a math contest, there are {n} three-dimensional vectors A_n = (x_n, y_n, z_n) for 1 ≤ n ≤ {n}. They satisfy the domain conditions that sqrt({r_x} + x_n), sqrt({r_y} + y_n), and sqrt({r_z} + z_n) are all real numbers for every n, and the following moment constraints:\n- ∑_{n=1}^{n} x_n^3 = 0 and ∑_{n=1}^{n} x_n^2 = {sum_x2}.\n- ∑_{n=1}^{n} z_n^3 = 0 and ∑_{n=1}^{n} z_n = {sum_z1}.\n- ∑_{n=1}^{n} (y_n + {r_y})(y_n - {c_y})^2 = 0 and ∑_{n=1}^{n} y_n = {sum_y1}.\n\nLet i = {i_index} and j = {j_index}. Find the maximum possible value of |A_i| / |A_j|.\n\nAfter solving the above problem, please output your final answer in the following format:\n### The final answer is: $\\boxed{<your answer>}$\nThe final answer should be given as precisely as possible (using LaTeX symbols such as \\sqrt, \\frac, \\pi, etc.). If the final answer involves a decimal approximation, it must be accurate to at least four decimal places.'

    class _RNGShim:
def __init__(self, seed: int):
    import random as _random
    self._seed = int(seed)
    self._r = _random.Random(self._seed)

def random(self): return self._r.random()
def uniform(self, a, b): return self._r.uniform(a, b)
def randint(self, a, b): return self._r.randint(a, b)
def randrange(self, *args): return self._r.randrange(*args)
def choice(self, seq): return self._r.choice(seq)
def choices(self, population, weights=None, cum_weights=None, k: int = 1):
    return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
def sample(self, population, k: int): return self._r.sample(population, k)
def shuffle(self, x):
    self._r.shuffle(x)
    return x
def getrandbits(self, k: int): return self._r.getrandbits(k)

    def generator(rng):
# Choose N as a multiple of 90 so both N/10 and 8N/9 are integers.
k = rng.randint(2, 8)
n = 90 * k

# Choose parameters so the extremal inequalities become tight at two-point supports.
# For x: use (x + r_x)(x - a)^2 >= 0 with r_x = a/2 (so linear term vanishes upon expansion).
a = rng.choice([2, 4, 6, 8])  # even integer
r_x = a // 2                  # integer

# For z: use (z + r_z)(z - b)^2 >= 0 with r_z = 2b (so the quadratic term vanishes upon expansion).
b = rng.choice([1, 2, 3])     # positive integer
r_z = 2 * b

# For y: enforce exactly two values via sum (y + r_y)(y - c_y)^2 = 0 and a separate sum to force mixture.
r_y = rng.choice([1, 2, 3, 4])
c_y = r_y + rng.randint(1, 7)  # ensure c_y > r_y >= 1

# Choose a nontrivial mixture count for y
m_y = rng.randint(1, n - 1)
sum_y1 = m_y * c_y - (n - m_y) * r_y

# Compute the extremal sums for x and z
# For x: sum x^3 = 0 and sum x^2 = n * a^2 / 3 (achieved by x in {a, -a/2} with counts n/10 and 9n/10)
sum_x2 = (n // 3) * (a * a)

# For z: sum z^3 = 0 and sum z = (2 n b) / 3 (achieved by z in {b, -2b} with counts 8n/9 and n/9)
sum_z1 = (2 * n * b) // 3

# Pick distinct indices i and j
i_index = rng.randint(1, n)
j_index = rng.randint(1, n)
if j_index == i_index:
    j_index = 1 if i_index != 1 else 2

return {
    'n': n,
    'r_x': r_x,
    'r_y': r_y,
    'r_z': r_z,
    'sum_x2': sum_x2,
    'sum_z1': sum_z1,
    'c_y': c_y,
    'sum_y1': sum_y1,
    'i_index': i_index,
    'j_index': j_index
}

    def verifier(assign):
# Validate presence of required keys
required = ['n', 'r_x', 'r_y', 'r_z', 'sum_x2', 'sum_z1', 'c_y', 'sum_y1', 'i_index', 'j_index']
for key in required:
    if key not in assign:
        # Missing data renders the instance invalid
        return (False, None)

n = assign['n']
r_x = assign['r_x']
r_y = assign['r_y']
r_z = assign['r_z']
sum_x2 = assign['sum_x2']
sum_z1 = assign['sum_z1']
c_y = assign['c_y']
sum_y1 = assign['sum_y1']
i_index = assign['i_index']
j_index = assign['j_index']

# Basic domain checks
if not (isinstance(n, int) and n >= 180 and n % 90 == 0):
    # Need enough vectors and integrality for the extremal counts
    return (False, None)
if not all(isinstance(v, int) for v in [r_x, r_y, r_z, sum_x2, sum_z1, c_y, sum_y1, i_index, j_index]):
    return (False, None)
if r_x <= 0 or r_y <= 0 or r_z <= 0 or c_y <= r_y:
    return (False, None)
if i_index < 1 or i_index > n or j_index < 1 or j_index > n or i_index == j_index:
    return (False, None)

# Recover the structural parameters a and b from r_x and r_z
# r_x = a/2, r_z = 2b with a even, b integer
a = 2 * r_x
if a % 2 != 0:
    return (False, None)
if r_z % 2 != 0:
    return (False, None)
b = r_z // 2

# Check the extremal sums coherence
# sum_x2 should be n * a^2 / 3
if sum_x2 != (n // 3) * (a * a):
    return (False, None)
# sum_z1 should be (2 n b) / 3
if sum_z1 != (2 * n * b) // 3:
    return (False, None)

# Verify that the induced counts are integers and nontrivial
m_x = n // 10        # number of x equal to a
if 10 * m_x != n or m_x < 1 or (n - m_x) < 1:
    return (False, None)
m_z = (8 * n) // 9   # number of z equal to b
if 9 * m_z != 8 * n or m_z < 1 or (n - m_z) < 1:
    return (False, None)

# From sum_y1 = m_y * c_y + (n - m_y) * (-r_y) -> m_y = (sum_y1 + n r_y)/(c_y + r_y)
denom_my = c_y + r_y
if denom_my == 0:
    return (False, None)
num_my = sum_y1 + n * r_y
if num_my % denom_my != 0:
    return (False, None)
m_y = num_my // denom_my
if not (1 <= m_y <= n - 1):
    return (False, None)

# Compute the extremal ratio: maximize |A_i| by taking (x, y, z) = (a, c_y, -2b);
# minimize |A_j| by taking (x, y, z) = (-a/2, -r_y, b).
import math
num_sq = (a ** 2) + (c_y ** 2) + ((2 * b) ** 2)
den_sq = ((a / 2) ** 2) + (r_y ** 2) + (b ** 2)
if den_sq <= 0:
    return (False, None)
answer = math.sqrt(num_sq / den_sq)

# A small sanity check: answer should be > 1 in all nontrivial instances
if not (answer > 1.0):
    return (False, None)

return (True, answer)


    def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
        """Return dict with assignment/question/answer or raise RuntimeError."""
        start = time.time()
        attempts = 0
        while time.time() - start < timeout_seconds:
            attempts += 1
            rng = _RNGShim(seed + attempts)
            assignment = generator(rng)
            valid, answer = verifier(assignment)
            if valid:
                question = LANGUAGE_WRAPPER.format(**assignment)
                return {
                    "assignment": assignment,
                    "question": question,
                    "answer": answer,
                    "attempts": attempts,
                    "elapsed_seconds": time.time() - start,
                }
        raise RuntimeError("Failed to sample a valid assignment within timeout_seconds")

